// The human checkout on a REAL Postgres (src/human-checkout.js with
// STATE_DATABASE_URL): the record directory is imported once at the first
// boot and never again, every record is a row (and, while the directory
// exists, a file), a paid session is generated by exactly one of two
// instances that fulfil it at once, a stale claim is taken over by exactly
// one of two sweeps, a failed report is refunded and an unrefunded one is
// owed on the row, and a published report is served by the synchronous
// public readers from the mirror. Requires STATE_DATABASE_URL (CI fails
// without it).
import { mkdtempSync, rmSync, writeFileSync, readFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, basename } from "node:path";
import { requireTestPg } from "./lib/test-pg.js";
requireTestPg({ label: "test-human-checkout-pg" });
const sdb = await import("../src/state-db.js");
const { createHumanCheckout, readPublicReport, listPublicReports, refreshPublicMirror, STALE_CLAIM_MS } = await import("../src/human-checkout.js");

let pass = 0, fail = 0;
const ok = (c, m) => { if (c) { pass++; console.log(`ok - ${m}`); } else { fail++; console.error(`FAIL - ${m}`); } };
const DIR = mkdtempSync(join(tmpdir(), "human-checkout-pg-"));
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
let clock = Date.parse("2026-10-01T12:00:00Z");
const now = () => clock;
const row = async (id) => (await sdb.stateQuery(`SELECT body FROM ${sdb.stateDbSchema()}.records WHERE collection = 'human-checkout' AND id = $1`, [id])).rows[0]?.body ?? null;
const file = (id) => { try { return JSON.parse(readFileSync(join(DIR, `${id}.json`), "utf8")); } catch { return null; } };

// The directory a previous build left: one delivered public report, one
// stale claim in flight, one owed refund.
const OLD_PUBLIC = "rp_oldoldoldoldold";
writeFileSync(join(DIR, "cs_done.json"), JSON.stringify({ status: "done", kind: "domain", slug: "domain-audit", input: "example.com", title: "example.com", report: "# Domain Security Audit: example.com\n\nText.", sources: [], tables: [], at: "2026-09-01T00:00:00.000Z", public: true, publicId: OLD_PUBLIC, publishedAt: "2026-09-02T00:00:00.000Z" }));
writeFileSync(join(DIR, "_public.json"), JSON.stringify({ [OLD_PUBLIC]: "cs_done" }));
writeFileSync(join(DIR, "cs_stale.json"), JSON.stringify({ status: "generating", kind: "dossier", slug: "dossier", at: new Date(clock - STALE_CLAIM_MS - 1000).toISOString(), claimedAt: clock - STALE_CLAIM_MS - 1000, takeovers: 0 }));
writeFileSync(join(DIR, "_inflight.json"), JSON.stringify({ cs_stale: clock - STALE_CLAIM_MS - 1000 }));
writeFileSync(join(DIR, "cs_owed.json"), JSON.stringify({ status: "error", refundId: null, error: "We couldn't complete this report. Your refund is being processed.", refundOwed: true, refundAttempts: 1, lastRefundAttemptAt: clock - 60_000, paymentIntent: "pi_owed", at: new Date(clock - 60_000).toISOString() }));
writeFileSync(join(DIR, "_issues.json"), JSON.stringify({ cs_owed: { kind: "refund-owed", at: new Date(clock - 60_000).toISOString(), attempts: 1 } }));

const sessions = {
  cs_paid: { id: "cs_paid", payment_status: "paid", payment_intent: "pi_ok", customer_details: { email: null }, metadata: { product: "dossier", input: "AAPL" } },
  cs_fail: { id: "cs_fail", payment_status: "paid", payment_intent: "pi_fail", metadata: { product: "research", input: "FAIL" } },
  cs_stale: { id: "cs_stale", payment_status: "paid", payment_intent: "pi_stale", metadata: { product: "dossier", input: "MSFT" } },
  cs_slow: { id: "cs_slow", payment_status: "paid", payment_intent: "pi_slow", metadata: { product: "dossier", input: "SLOW" } },
};
let refunds = [];
let refundFail = false;
let genCalls = 0;
const stripe = {
  checkout: { sessions: { retrieve: async (id) => { await wait(15); const s = sessions[id]; if (!s) throw new Error("No such session"); return s; } } },
  refunds: { create: async (args) => { if (refundFail) throw new Error("stripe refund down"); refunds.push(args); return { id: "re_" + refunds.length }; } },
};
const sales = [];
const generate = async (kind, slug, input) => {
  genCalls++;
  if (input === "FAIL") throw new Error("upstream boom");
  if (input === "SLOW") await wait(150);
  return { report: `# REPORT (${slug})\n\nAnalysis of ${input}. [1]`, title: `T:${input}`, sources: [], tables: [] };
};
const mk = () => createHumanCheckout({ stripe, generate, baseUrl: "https://agent402.tools", storeDir: DIR, onSale: (s) => sales.push(s), now, log: () => {} });
async function settle(hc, id, tries = 100) {
  for (let i = 0; i < tries; i++) { const r = await hc.peek(id); if (r && r.status !== "generating") return r; await wait(10); }
  return hc.peek(id);
}

try {
  // ---- (1) import once ------------------------------------------------------
  const A = mk();
  ok(A.backend === "pg", "the store is on the database");
  await A.ready();
  ok(!!(await sdb.imports.done(basename(DIR))), "the directory import is marked under its basename");
  ok((await row("cs_done"))?.publicId === OLD_PUBLIC && (await row("_inflight"))?.cs_stale > 0 && (await row("_issues"))?.cs_owed?.kind === "refund-owed", "records and the three indexes were imported as rows");
  ok((await A._count()) === 3, "three report records");
  writeFileSync(join(DIR, "cs_late.json"), JSON.stringify({ status: "done", kind: "dossier", slug: "dossier", input: "LATE", report: "# late", at: "2026-09-01T00:00:00.000Z" }));
  const B = mk();
  await B.ready();
  ok((await B.peek("cs_late")) === null && (await row("cs_late")) === null, "a second boot does not import again");

  // ---- the public readers serve the mirror, synchronously -------------------
  await refreshPublicMirror();
  const view = readPublicReport(OLD_PUBLIC, "/nonexistent");
  ok(view?.publicView === true && view.input === "example.com" && listPublicReports("/nonexistent").some((r) => r.publicId === OLD_PUBLIC), "an imported public report is served by the synchronous readers from the mirror (no directory needed)");
  ok(readPublicReport("rp_000000000000000000") === null && readPublicReport("cs_done") === null, "unknown and session-shaped ids read nothing");

  // ---- (2) generate once across two instances --------------------------------
  const [f1, f2] = await Promise.all([A.fulfill("cs_slow"), B.fulfill("cs_slow")]);
  ok(f1.status === "generating" && f2.status === "generating", "both instances answer generating to the buyer");
  const done = await settle(A, "cs_slow");
  await settle(B, "cs_slow");
  ok(done.status === "done" && genCalls === 1 && sales.length === 1, `two instances fulfilling one paid session at once generate it ONCE (generate calls: ${genCalls})`);
  ok((await row("cs_slow"))?.status === "done" && (await row("_inflight"))?.cs_slow === undefined, "the delivered record is the row and the in-flight index no longer lists it");
  ok(file("cs_slow")?.status === "done" && file("_inflight")?.cs_slow === undefined, "the record and the index are written through to the directory");
  ok((await B.fulfill("cs_slow")).status === "done" && genCalls === 1, "a later poll on the other instance reads the row and does not regenerate");

  // ---- (3) the stale claim is taken over by exactly one sweep --------------
  const before = genCalls;
  const [r1, r2] = await Promise.all([A.recoverAbandoned(), B.recoverAbandoned()]);
  await settle(A, "cs_stale");
  ok(genCalls === before + 1 && (await row("cs_stale"))?.status === "done", `two boot sweeps over one stale claim regenerate it once (${JSON.stringify([r1, r2].map((r) => r.map((x) => x.result)))})`);
  // A record another container finished is never overwritten by a claim.
  const [f3, f4] = await Promise.all([A.fulfill("cs_paid"), B.fulfill("cs_paid")]);
  const paid = await settle(A, "cs_paid");
  ok(f3.status === "generating" && f4.status === "generating" && paid.status === "done" && genCalls === before + 2, "a fresh paid session fulfilled by both instances is generated once");

  // ---- (4) a failed report is refunded; a failed refund is owed on the row --
  refundFail = true;
  await A.fulfill("cs_fail");
  const failed = await settle(A, "cs_fail");
  ok(failed.status === "error" && failed.refundOwed === true && !failed.refundId && (await row("_issues"))?.cs_fail?.kind === "refund-owed", "a failed report whose refund fails is persisted as OWED and indexed");
  const issues = await B.listIssues();
  ok(issues.refundOwed.some((x) => x.id === "cs_fail") && issues.refundOwed.some((x) => x.id === "cs_owed") && issues.inflight.length === 0, "listIssues on the other instance reads the rows");
  refundFail = false;
  clock += 60_000;
  const retried = await B.fulfill("cs_fail");
  ok(retried.status === "error" && retried.refundId === "re_1" && retried.refundOwed === false && (await row("_issues"))?.cs_fail === undefined, "a later poll retries the owed refund, succeeds, and clears the issue");
  const owed = await A.fulfill("cs_owed");
  ok(owed.refundId === "re_2" && owed.refundOwed === false && file("cs_owed")?.refundId === "re_2", "an imported owed refund is retried and the outcome written through");

  // ---- (5) the public toggle updates the row and the mirror -----------------
  const pubOn = await A.setPublic("cs_paid", true);
  ok(pubOn.status === "done" && /^rp_/.test(pubOn.publicId) && readPublicReport(pubOn.publicId)?.input === "AAPL" && (await row("_public"))?.[pubOn.publicId] === "cs_paid", "publishing mints the id on the row, in the index and in the mirror");
  const pubOff = await A.setPublic("cs_paid", false);
  ok(pubOff.public === false && readPublicReport(pubOn.publicId) === null && !listPublicReports().some((r) => r.publicId === pubOn.publicId), "revoking drops it from the mirror and the list");
  ok((await B.setPublic("cs_nope_0000", true)).status === "not_found" && (await B.setPublic("junk", true)).status === "invalid", "publishing needs a real, delivered session id");
  await B.setPublic("cs_paid", true);
  await refreshPublicMirror();
  ok(readPublicReport(pubOn.publicId)?.publicId === pubOn.publicId && file("cs_paid")?.public === true, "a re-publish from the other instance reaches this mirror on refresh, and the file");
  ok(existsSync(join(DIR, "cs_paid.json")), "the record file exists for the write-through");
} finally {
  await sdb.__dropStateSchema().catch(() => {});
  await sdb.closeStateDb();
  rmSync(DIR, { recursive: true, force: true });
}
console.log(`\ntest-human-checkout-pg: ${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
